const rand = (...a) => {
  if(a.length == 1 && Array.isArray(a[0])) return a[0][(Math.random()*(a[0].length-1))|0];
  if(a.length == 1  && typeof a[0] == 'number') return Math.random()*a[0];
  if(a.length == 2  && typeof a[0] == 'number' && typeof a[1] == 'number') return Math.random()*(a[1]-a[0])+a[0];
  return Math.random();
}
const mix = (a,b,f) => (typeof a == 'number') ? a*(1-f)+b*f : a.map((_,i)=>mix(a[i], b[i], f))
