const shaderOp = (vs,fs,fn) => {
  let sh;
  return (uniforms={}, ...args) => {
    if(sh === undefined) sh = new p5.Shader(undefined, vs, fs)
    shader(sh)
    Object.entries(uniforms).forEach(([n,v])=>sh.setUniform(n,v))
    fn(...args)
    resetShader()
  }
}

