const ratio = 1/sqrt(2);
const offset = 0;
const max_anims = 4;
let w, h, pd, canvas, t=0, debug_t = false, debug_g = false, gui;

const colourModes = [
`shape * min(abs(lv.y),abs(lv.x))`,
`shape * min(abs(lv.x), min(abs(lv.y), min(abs(dv.y),abs(dv.x))))`,
`shape * abs((lv.y)+(lv.x))*2.`,
`shape * (abs(dv.y)*abs(dv.x))*mix(10.,2.,ringD)`,
`smoothstep(-mix(RING_D_MIN, RING_D_MAX, ringD), length(op), d) * shape`,
`smoothstep(-1., length(q), mix(sin(d*PI*2.),shape,ringD))*shape`,
`shape * abs(lv.y)`,
`shape * abs(lv.x)`,
`shape-clamp(d,-1.,0.)*2.`,
`shape*length(uv)`,
`pow(length(op*shape),length(op))`,
];

const tfn = [
  (t=>t*t*(3-2*t)),
  (t=>t*t/(2*t*t-2*t+1)),
  (t=>t<.5?2*t*t:2*t*(2-t)-1),
  (t=>.5-.5*cos(PI*t)),
];

const opt = (steps = [0,1], odds = .5, reset = false, durBase = 3, durSway = 1.5, max_group = 3,) => ({ steps, durBase, durSway, reset, odds, max_group })

let opts = {
  zoom: opt([0,.25,.5,.75,1]),
  xrep: opt(),
  yrep: opt(),
  polar: opt([0,1], .25),
  ringD: opt([0,.5,.75,1], .75),
  ringF: opt(),
  scrollX: opt([-1,0,1],.5,true),
  scrollY: opt([-1,0,1],.5,true),
  rotate: opt([-1,0,1],.5,true),
  grow: opt(),
  ...Object.fromEntries(colourModes.map((m,i)=>[`colour_${i}`, opt()])),
}

let params = Object.fromEntries(Object.entries(opts).map(([n,v])=>[n,0]));

let gui_params = {...params};

const genOpt = n => ({n, st: t, reset: opts[n].reset, d: opts[n].durBase+rand(-opts[n].durSway, opts[n].durSway), f: rand(tfn), sv: params[n], tv: rand(opts[n].steps.filter(v=>v!==params[n]))})

let queue = [];

//super normal and readable single statement function here
const genOpts = _ => {
  let c = (rand(Object.entries(opts).filter(([n,v])=>
      !queue.some(q=>q.n==n) &&
      rand()>v.odds &&
      (n.includes('_') ?
        [...Object.entries(params).map(([n,v])=>({n, tv:v})), ...queue].filter(q=>q.n.includes(n.split("_")[0])).reduce((a,v)=>a+v.tv,0) < v.max_group
        && [...Object.entries(params).map(([n,v])=>({n, tv:v})), ...queue].filter(q=>q.n.includes(n.split("_")[0])).reduce((a,v)=>a+v.tv,0)-(1-params[n]) > 0 //this line is a disgusting hack that doesn't even work lmao oh well its 2am
       :
       true))))
  if(c!==undefined) queue.push(genOpt(c[0]))
}

let consts = {
  ZOOM_MIN: 1,
  ZOOM_MAX: 12,
  RING_D_MIN: .5,
  RING_D_MAX: 4.,
  RING_F_MIN: .1,
  RING_F_MAX: 1.5,
}

//noprotect
const rainbow = slabOp(`
precision highp float;

#define PI ${PI}
#define TAU ${TAU}

${Object.entries(consts).map(([n,v])=>`#define ${n} ${v.toFixed(1)}`).join("\n")}

varying vec2 uv;

uniform float t, ratio, pd;
uniform vec2 offset;
uniform float ${Object.keys(params).join(",")};

${glsl.spectral_zucconi6}
${glsl.rot}
${glsl.snoise2d}

#define RANGE ${(Math.ceil(consts.RING_D_MAX+consts.RING_F_MAX)).toFixed(1)}

void main() {
  // take screen position in range -1:1 and scale it for aspect ratio
  vec2 p = (uv*2.-1.)*max(vec2(1.),vec2(ratio, 1./ratio))-offset;

  // save original position for later
  vec2 op = p;

  //background colour
  vec3 col = vec3(.05);

  //zoom
  float zl = mix(ZOOM_MIN,ZOOM_MAX-polar*ZOOM_MAX*.5,zoom);

  //repeat range
  vec2 rl = mix(vec2(zl*.5), vec2(PI*zl*.5, PI*zl*(1./PI)*.5), polar)*vec2(xrep,yrep);

  //do the transforms
  p.y -= polar*1.*scrollY;
  p *= rot(.5*PI);
  p = mix(p, vec2(log2((length(p)+.5)), atan(p.y,p.x)), polar);
  p *= rot(rotate*PI*2.);
  p = fract(p*.5+.5+vec2(scrollX,scrollY*(1.-polar)))*2.-1.;

  //scale to the zoom level
  p *= zl;

  //calculate spectral value for grid neighbors
  float spec = 0.;
  for(float i = 0.; i < (RANGE*2.)*(RANGE*2.); i++) {
    float s = 0.;
    vec3 c = vec3(0);
    vec2 q = p;

    vec2 off = vec2(i/(RANGE*2.)-floor(RANGE*.5+.5), mod(i,RANGE*2.)-floor(RANGE*.5+.5))*sign(p);
    vec2 id = floor(q*.5+off+.5);

    //actually make the grid
    vec2 ea = step(abs(id), rl);
    q -= mix(rl*2.*sign(id), 2.*id, ea);

    //make new grid elements "grow"
    q = mix(q, q/mix(1., mix(.01, 1., mix(fract(max(rl.x*ea.y, rl.y*ea.x)), fract(rl.x)*fract(rl.y), 1.-step(1.,ea.x+ea.y))), 1.-step(2., ea.x+ea.y)), grow);

    float d = length(q)-mix(RING_D_MIN, RING_D_MAX, ringD);
    vec2 dv = (p/length(p));
    vec2 lv = (q/length(q));

    float shape = (1.-smoothstep(0., mix(RING_F_MIN, RING_F_MAX, ringF), d));

    //generate code to apply the selected colourModes. this m
    float ct = ${colourModes.map((m,i)=>`colour_${i}`).join("+")} + 1.;
    // ${colourModes.map((m,i)=>`s += (${m})*${i==0?`mix(colour_0, 1., step(ct,0.))`:`colour_${i}`};`).join("\n")}
    ${colourModes.map((m,i)=>`s += (${m})*${i==0?`1.`:`colour_${i}`};`).join("\n")}
    s /= mix(ct, 1.,step(ct,0.));

    s = pow(s, 1./2.2);

    spec += s * (step(dot(step(rl+1., abs(id)), vec2(1)), 0.));
  }

  spec = fract(spec);

  col = mix(col, spectral_zucconi6(spec*300.+400.), smoothstep(0., pd*.25, spec)*(.9+.2*dot(col, vec3(1))/3.));

  gl_FragColor = vec4(col,1);
}
`)


draw = _ => {
  t+=deltaTime/1000;

  queue = queue.filter(({st,d,reset,n,sv})=>(t-st)<d)
  queue.forEach(({st,d,reset,n,sv})=>params[n]=(reset?sv:params[n]))
  queue.forEach(({n, st, sv, tv, f, d})=>params[n] = mix(sv, tv, f((t-st)/d)))

  if(queue.length < max_anims) genOpts()

  normalise_p5(ratio);
  rainbow({t:debug_t?((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/w):(t%6/6), ratio, pd, offset: (ratio<1?[0,offset]:[offset,0]), ...debug_g?gui_params:params})
}

windowResized = _ =>{ w = min(windowWidth, windowHeight * ratio); h = w/ratio; pd = 2/max(w,h); resizeCanvas(1112,834); }

setup =  _ => {
  pixelDensity(2);
  colorMode(RGB, 1, 1, 1, 1);
  rectMode(CENTER)
  canvas = createCanvas(1112,834,WEBGL);
  windowResized()

  gui = new dat.GUI({})
  gui.remember(gui_params);
  Object.keys(gui_params).forEach(n=>gui.add(gui_params, n, 0, 1, .001).listen())
  debug_g ? gui.show() : gui.hide()
}

keyPressed = _ => {
  switch(keyCode) {
    case "T".charCodeAt():
      debug_t = !debug_t;
      break;
    case "G".charCodeAt():
      debug_g = !debug_g;
      debug_g ? gui.show() : gui.hide()
      gui_params = Object.assign(gui_params, params)
      break;
  }
}

